def unpack(name):return lzma.decompress(base64.b85decode(SOURCES[name])).decode()
CERT=json.loads(unpack('certificate'))
PARAMETERS=CERT['parameters']
HIT_LIMIT=CERT['hit_limit']
def load_modules():
 step=types.ModuleType('normative_step');exec(compile(unpack('step'),'normative_step.py','exec'),step.__dict__)
 base=types.ModuleType('emitter');sys.modules['emitter']=base;exec(compile(unpack('controller_base'),'controller_base.py','exec'),base.__dict__)
 ctl=types.ModuleType('normative_controller');exec(compile(unpack('controller'),'normative_controller.py','exec'),ctl.__dict__)
 support=types.ModuleType('experiment_support');exec(compile(unpack('support'),'experiment_support.py','exec'),support.__dict__)
 model=types.ModuleType('certificate_model');exec(compile(unpack('model'),'certificate_model.py','exec'),model.__dict__)
 return step,ctl,support,model

